const $=s=>document.querySelector(s);
const esc=value=>String(value??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
const fmt=n=>Number(n||0).toLocaleString("en-US");
const DAY=86400000;
const claimExpiry=a=>a.expiresAt||new Date(new Date(a.claimedAt||Date.now()).getTime()+7*DAY).toISOString();
const expired=a=>a.status!=="redeemed"&&!a.redeemedAt&&Date.now()>new Date(claimExpiry(a)).getTime();
const expiryLabel=a=>new Date(claimExpiry(a)).toLocaleDateString("en-US",{month:"short",day:"numeric",year:"numeric"});
const daysLeft=a=>Math.max(0,Math.ceil((new Date(claimExpiry(a)).getTime()-Date.now())/DAY));
const redemptionCode=a=>a.redemptionCode||("FG-"+a.id.replace(/[^a-z0-9]/gi,"").slice(0,10).toUpperCase());

const uid=()=>typeof crypto!=="undefined"&&crypto.randomUUID?crypto.randomUUID():Math.random().toString(36).slice(2);
