const videosForMe=()=>state.videos.filter(v=>v.studentId===state.activeStudent);
function load(){try{const v=JSON.parse(localStorage.getItem(STORAGE));if(v&&Array.isArray(v.claims)&&Array.isArray(v.videos)&&Array.isArray(v.campaigns)&&Array.isArray(v.students)&&Array.isArray(v.businesses))return {...seed(),...v,tab:"explore",detail:null,friendPreview:false,selectedRestaurant:null,selectedCampaign:null};}catch{}return seed()}
function persist(){try{localStorage.setItem(STORAGE,JSON.stringify(state))}catch{toast("Browser storage is unavailable; changes may not persist.")}}
function toast(message){const el=$("#toast");el.textContent=message;el.classList.add("show");clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>el.classList.remove("show"),3200)}
function img(src,alt,extra=""){
 const isCoffee=/coffee|nitro|espresso/i.test(src+" "+alt);
 const isPastry=/pastry|breakfast|toast/i.test(src+" "+alt);
 const isBowl=/bowl|dinner|noodles/i.test(src+" "+alt);
 const emoji=isCoffee?"☕":isPastry?"🥐":isBowl?"🍜":"🥪";
 const subtitle=isCoffee?"A LITTLE COFFEE MOMENT":isPastry?"YOUR NEXT FAVORITE BITE":isBowl?"A TABLE WORTH SHARING":"LUNCH PLANS, SORTED";
 const fallback=src===PHOTO.nitroCoffee?"https://images.pexels.com/photos/312418/pexels-photo-312418.jpeg?auto=compress&cs=tinysrgb&w=1000":src===PHOTO.poppyBakery?"https://images.pexels.com/photos/3639538/pexels-photo-3639538.jpeg?auto=compress&cs=tinysrgb&w=1000":"";
 return '<div class="photo-surface" role="img" aria-label="'+esc(alt)+'"><div class="photo-backdrop"><span class="photo-stamp">FUSE / FOOD</span><span class="photo-plate">'+emoji+'</span><span class="photo-caption">'+subtitle+'</span></div><img class="actual-photo" src="'+esc(src)+'" '+(fallback?'data-photo-backup="'+esc(fallback)+'"':'')+' alt="" loading="lazy" '+extra+'></div>';
}
document.addEventListener("error",event=>{
 const node=event.target;
 if(node&&((node.tagName==="VIDEO"&&node.classList.contains("reel-video"))||(node.tagName==="SOURCE"&&node.parentElement?.classList.contains("reel-video")))){const vid=node.tagName==="SOURCE"?node.parentElement:node;vid.hidden=true;vid.closest(".reel-stage")?.classList.add("video-failed");return;}
 if(node&&node.tagName==="IMG"&&node.classList.contains("actual-photo")){
   if(node.dataset.photoBackup&&!node.dataset.photoBackupAttempted){node.dataset.photoBackupAttempted="true";node.src=node.dataset.photoBackup;return;}
   node.hidden=true;
   node.closest(".photo-surface")?.classList.add("image-failed");
 }
},true);
function tag(text,kind=""){return '<span class="status '+kind+'">'+esc(text)+'</span>'}
function btn(label,action,id="",style="button",attrs=""){return '<button type="button" class="'+style+'" data-action="'+esc(action)+'" data-id="'+esc(id)+'" '+attrs+'>'+label+'</button>'}
function nav(){const options=state.role==="student"?[["explore","⌂","Explore"],["forYou","♡","For You"],["friends","♧","Friends"],["content","▣","My Content"],["profile","◯","Profile"]]:[["overview","▦","Overview"],["create","✳","Create"],["creators","♧","Creators"],["videos","▣","Videos"]];$("#bottomNav").innerHTML=options.map(([id,symbol,label])=>'<button type="button" data-tab="'+id+'" class="'+(state.tab===id?"active":"")+'" aria-current="'+(state.tab===id?"page":"false")+'"><span class="nav-icon">'+symbol+'</span><span>'+label+'</span></button>').join("");$("#roleSwitch").innerHTML=state.role==="student"?'Creator <span>⇄</span>':'Business <span>⇄</span>'}
function heading(kicker,title,sub){return '<p class="eyebrow">'+kicker+'</p><h1 class="page-title">'+title+'</h1>'+(sub?'<p class="subhead">'+sub+'</p>':"")}
function available(c){return Math.max(0,c.spots-claimsFor(c.id).filter(a=>!expired(a)).length)}
function capacity(c){return available(c)+' of '+c.spots+' spots left'}
function render(){nav();const screens={explore,forYou,friends,visits,content,profile,referrals,overview,create,creators,videos};let html;if(state.detail?.type==="offer")html=offerDetail(state.detail.id);else if(state.detail?.type==="claimed")html=claimedScreen(state.detail.id);else if(state.detail?.type==="friend")html=friendScreen(state.detail.id);else if(state.detail?.type==="restaurant")html=restaurantDetail(state.detail.id);else if(state.detail?.type==="video")html=videoDetail(state.detail.id);else if(state.detail?.type==="campaign")html=campaignResult(state.detail.id);else if(state.detail?.type==="qr")html=qrScreen(state.detail.id);else html=screens[state.tab]();$("#content").innerHTML=html;if(state.tab==="explore"&&state.mapVisible&&!state.detail)requestAnimationFrame(initMap);if(state.tab==="profile"&&state.role==="student")requestAnimationFrame(updateTikTokBadge);if(state.tab==="content"&&state.role==="student"&&state.contentSection==="posts")requestAnimationFrame(loadTikTokFeed);if(state.detail?.type==="qr")requestAnimationFrame(drawQR);}
function goTab(tab){state.tab=tab;state.detail=null;render();$("#content").scrollTop=0}
function goDetail(type,id){state.detail={type,id};render();$("#content").scrollTop=0}
function imageTag(c){return c.comp==="cash"?'<span class="image-tag red">COVERED VISIT · '+esc(c.reward)+'</span>':'<span class="image-tag">'+esc(c.reward)+'</span>'}
function offerChips(c){return '<div class="chips">'+(c.duo?'<span class="chip duo-chip">✳ YOU + A FRIEND</span>':'<span class="chip">SOLO</span>')+'<span class="chip">⌁ '+esc(c.neighborhood)+'</span><span class="chip">'+esc(c.reward)+'</span><span class="chip">'+esc(capacity(c))+'</span></div>'}
function featureCard(c){const b=business(c.businessId);return '<button type="button" data-action="offer" data-id="'+esc(c.id)+'" class="feature-card featured-pressable"><div class="feature-image">'+img(c.image,c.title)+imageTag(c)+'</div><div class="feature-body"><div class="feature-overline"><span class="eyeline">'+esc(b.name)+' · '+esc(c.neighborhood)+'</span><span class="feature-rating">✳ FEATURED</span></div><h3>'+esc(c.title)+'</h3><div class="featured-info"><span>✦ '+esc(c.reward)+'</span><span>◉ '+esc(capacity(c))+'</span></div><p class="card-summary">'+esc(c.description)+'</p><div class="featured-card-bottom"><span>See what’s included</span><span class="feature-card-arrow" aria-hidden="true">↗</span></div></div></button>'}
function smallCard(c){const b=business(c.businessId);return '<article class="offer-card"><div class="small-image">'+img(c.image,c.title)+'</div><div class="offer-body"><div class="eyeline">'+esc(c.neighborhood)+' · '+esc(b.name)+'</div>'+(c.duo?'<span class="duo-label">✳ YOU + A FRIEND</span>':'<span class="solo-label">SOLO</span>')+'<h3>'+esc(c.title)+'</h3><p class="card-summary">'+esc(c.reward)+' · '+esc(capacity(c))+'</p>'+btn("View offer →","offer",c.id,"button text")+'</div></article>'}
